 void Hover(object s,DragEventArgs e){if(e.Data.GetDataPresent(typeof(DragInfo)))e.Effect=DragDropEffects.Copy|DragDropEffects.Move;}
 public void Remember(){undo.Push(ProjectIO.Json(Project));if(undo.Count>80)undo=new Stack<string>(undo.Take(80).Reverse());redo.Clear();}
 public void Changed(){if(Preview!=null&&designer!=null&&!designer.Checked)Preview.Stop();dirty=true;Text="EasyJava 2 — "+ProjectIO.Safe(Project.Name)+" *";if(previewTimer!=null){previewTimer.Stop();previewTimer.Start();}counter.Text=ProjectIO.Count(Project.Blocks)+" bloczków";status.Text="Zmieniono projekt • F5: podgląd • Ctrl+Enter: kompiluj • ●: wyłącz bloczek";}
 public void Render(){if(workspace==null||rendering||workspace.ClientSize.Width<200)return;rendering=true;loading=true;try{Point scroll=workspace.AutoScrollPosition;workspace.SuspendLayout();foreach(Control c in workspace.Controls.Cast<Control>().ToArray())c.Dispose();Cards.Clear();int width=Math.Max(365,workspace.ClientSize.Width-SystemInformation.VerticalScrollBarWidth-4);NodeList nodes=new NodeList(this,Project.Blocks,width,false);workspace.Controls.Add(nodes);workspace.ResumeLayout(true);workspace.AutoScrollPosition=new Point(-scroll.X,-scroll.Y);lastWidth=workspace.ClientSize.Width;counter.Text=ProjectIO.Count(Project.Blocks)+" bloczków";name.Text=Project.Name;Text="EasyJava 2 — "+ProjectIO.Safe(Project.Name)+(dirty?" *":"");Preview.Project=Project;}finally{loading=false;rendering=false;}}
 public void RenderPalette(){if(palette==null)return;palette.SuspendLayout();foreach(Control c in palette.Controls.Cast<Control>().ToArray())c.Dispose();int y=3;int itemWidth=Math.Max(120,palette.ClientSize.Width-SystemInformation.VerticalScrollBarWidth-22);string term=search.Text.Trim().ToLowerInvariant(),category=categories.SelectedIndex<=0?null:categories.Text;foreach(string group in Catalog.Groups){if(category!=null&&group!=category)continue;var specs=Catalog.All.Values.Where(s=>s.Group==group&&(s.Name+" "+s.Hint).ToLowerInvariant().Contains(term)).ToList();if(specs.Count==0)continue;Color color=Catalog.ColorFor(group);Label title=Ui.Label(group.ToUpperInvariant()+(Project.Allows(group)?"":" • WYŁĄCZONE"),8);title.ForeColor=color;title.Font=new Font("Segoe UI",8,FontStyle.Bold);title.SetBounds(12,y,itemWidth,25);palette.Controls.Add(title);y+=28;foreach(Spec s in specs){Spec spec=s;Button b=Ui.Button(s.Name,Project.Allows(group)?color:Ui.Raised);b.Font=new Font("Segoe UI",9,FontStyle.Bold);b.TextAlign=ContentAlignment.MiddleLeft;b.Padding=new Padding(6,0,0,0);b.SetBounds(10,y,itemWidth,s.Name.Length>21?52:40);Tips.SetToolTip(b,s.Hint);Point start=Point.Empty;bool dragged=false;b.MouseDown+=delegate(object o,MouseEventArgs a){start=a.Location;dragged=false;};b.MouseMove+=delegate(object o,MouseEventArgs a){if(a.Button==MouseButtons.Left&&!dragged&&Math.Abs(a.X-start.X)+Math.Abs(a.Y-start.Y)>6){dragged=true;b.DoDragDrop(new DragInfo{Kind=spec.Kind},DragDropEffects.Copy);}};b.Click+=delegate{if(!dragged)AddBlock(spec.Kind);};palette.Controls.Add(b);y+=b.Height+6;}y+=14;}palette.ResumeLayout();}
 void AddBlock(string kind){if(ProjectIO.Count(Project.Blocks)>=2000){Error("Limit 2000 bloczków.");return;}Remember();Block b=Block.Make(kind);if(kind.StartsWith("ui_")&&Catalog.All[kind].Fields.Length==6){string root=b.A.TrimEnd('1');int i=1;HashSet<string> ids=new HashSet<string>(Flatten(Project.Blocks).Select(x=>x.A));while(ids.Contains(root+i))i++;b.A=root+i;b.C="30";b.D=(40+40*(i-1)).ToString();}Project.Blocks.Add(b);Changed();Render();BeginInvoke((Action)delegate{workspace.AutoScrollPosition=new Point(0,workspace.Controls[0].Height);});}
 public static IEnumerable<Block> Flatten(List<Block> nodes){foreach(Block b in nodes){yield return b;foreach(Block a in Flatten(b.Children))yield return a;foreach(Block a in Flatten(b.Else))yield return a;}}
 List<Block> FindOwner(List<Block> list,Block node){if(list.Contains(node))return list;foreach(Block b in list){List<Block> o=FindOwner(b.Children,node)??FindOwner(b.Else,node);if(o!=null)return o;}return null;}
 bool Contains(Block b,List<Block> list){return b.Children==list||b.Else==list||b.Children.Any(x=>Contains(x,list))||b.Else.Any(x=>Contains(x,list));}
 public void Drop(DragEventArgs args,List<Block> target,int index){DragInfo data=args.Data.GetData(typeof(DragInfo)) as DragInfo;if(data==null)return;if(data.Block!=null&&Contains(data.Block,target)){status.Text="Nie można umieścić bloczka we własnym wnętrzu.";return;}string snapshot=ProjectIO.Json(Project);try{Block b=data.Block??Block.Make(data.Kind);List<Block> from=data.Block==null?null:FindOwner(Project.Blocks,b);if(from!=null){int old=from.IndexOf(b);if(from==target&&old<index)index--;from.Remove(b);}target.Insert(Math.Max(0,Math.Min(target.Count,index)),b);ProjectIO.Normalize(Project);undo.Push(snapshot);redo.Clear();Changed();Render();}catch(Exception e){Project=ProjectIO.FromJson(snapshot);Render();Error(e.Message);}}
 public void NodeAction(Block b,List<Block> list,int action){int i=list.IndexOf(b);if(i<0||(action==2&&i==0)||(action==3&&i==list.Count-1))return;Remember();if(action==0)b.Disabled=!b.Disabled;else if(action==1)b.Collapsed=!b.Collapsed;else if(action==2||action==3){list.RemoveAt(i);list.Insert(i+(action==2?-1:1),b);}else if(action==4){Project t=new Project();t.Blocks.Add(b);Block clone=ProjectIO.FromJson(ProjectIO.Json(t)).Blocks[0];if(ProjectIO.Count(Project.Blocks)+1+ProjectIO.Count(clone.Children)+ProjectIO.Count(clone.Else)>2000){Error("Limit 2000 bloczków.");return;}list.Insert(i+1,clone);}else list.RemoveAt(i);Changed();Render();}
 void Highlight(Block b){if(highlighted!=null&&Cards.ContainsKey(highlighted)){Cards[highlighted].Active=false;Cards[highlighted].Invalidate();}highlighted=b;if(b!=null&&Cards.ContainsKey(b)){Cards[b].Active=true;Cards[b].Invalidate();}}
 async Task ShowDesign(){try{await Preview.Design(Project);}catch(Exception e){status.Text=e.Message;}}
 void UpdateCode(){try{string all=ProjectIO.Export(Project,Application.ExecutablePath);string[] lines=all.Split('\n');code.Text=string.Join("\r\n",lines.Select(l=>l.Length>1000?l.Substring(0,90)+" … [osadzone dane: "+l.Length+" znaków]":l).ToArray());}catch(Exception e){code.Text=e.Message;}}
 void Undo(){if(undo.Count==0)return;Preview.Stop();redo.Push(ProjectIO.Json(Project));Project=ProjectIO.FromJson(undo.Pop());Changed();Render();RenderPalette();}
 void Redo(){if(redo.Count==0)return;Preview.Stop();undo.Push(ProjectIO.Json(Project));Project=ProjectIO.FromJson(redo.Pop());Changed();Render();RenderPalette();}
 bool CanClose(){if(!dirty)return true;DialogResult r=MessageBox.Show(this,"Zapisać zmiany projektu „"+Project.Name+"” w pliku .js?","EasyJava",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);return r==DialogResult.No||(r==DialogResult.Yes&&Save(false));}
 void New(){if(!CanClose())return;Preview.Stop();Project=new Project();filePath=null;dirty=false;undo.Clear();redo.Clear();designer.Checked=false;Preview.Reset(Project);Render();RenderPalette();status.Text="Nowy pusty projekt • dodaj pierwszy bloczek";}
 void Open(){if(!CanClose())return;using(OpenFileDialog d=new OpenFileDialog{Filter="Projekty EasyJava (*.js)|*.js|Starszy projekt (*.easyjava)|*.easyjava",Title="Otwórz projekt .js"}){if(d.ShowDialog(this)!=DialogResult.OK)return;try{Project p=ProjectIO.Read(d.FileName);Preview.Stop();Project=p;filePath=d.FileName;dirty=false;undo.Clear();redo.Clear();Preview.Reset(Project);Render();RenderPalette();status.Text="Wczytano projekt: "+d.FileName;RememberPath();}catch(Exception e){Error(e.Message);}}}
 bool Save(bool saveAs){try{string target=filePath;if(saveAs||target==null||!target.EndsWith(".js",StringComparison.OrdinalIgnoreCase))using(SaveFileDialog d=new SaveFileDialog{Filter="Program i projekt JavaScript (*.js)|*.js",DefaultExt="js",AddExtension=true,FileName=ProjectIO.Safe(Project.Name)+".js",InitialDirectory=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)}){if(d.ShowDialog(this)!=DialogResult.OK)return false;target=d.FileName;if(!target.EndsWith(".js",StringComparison.OrdinalIgnoreCase))target+=".js";}
  ProjectIO.Write(target,Project,Application.ExecutablePath);filePath=target;dirty=false;Text="EasyJava 2 — "+Project.Name;status.Text="Zapisano działający i edytowalny plik: "+target;RememberPath();return true;
 }catch(Exception e){Error(e.Message);return false;}}
 void RememberPath(){try{Directory.CreateDirectory(settingsDir);File.WriteAllText(Path.Combine(settingsDir,"ostatni.txt"),filePath);}catch(IOException){}catch(UnauthorizedAccessException){}}
 void Export(){try{if(ProjectIO.Count(Project.Blocks)==0){Error("Dodaj bloczki przed kompilowaniem.");return;}string desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),target=Path.Combine(desktop,ProjectIO.Safe(Project.Name)+".js"),link=Path.Combine(desktop,"Otwórz "+ProjectIO.Safe(Project.Name)+".lnk");if((File.Exists(target)||File.Exists(link))&&MessageBox.Show(this,"Zastąpić plik projektu na pulpicie?\n"+target,"Kompiluj",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;ProjectIO.Write(target,Project,Application.ExecutablePath);ProjectIO.Shortcut(link,target,Application.ExecutablePath);filePath=target;dirty=false;RememberPath();Text="EasyJava 2 — "+Project.Name;status.Text="Gotowe! "+target;using(Form done=new Form{Text="Projekt gotowy",Size=new Size(510,235),BackColor=Ui.Panel,ForeColor=Ui.Text,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){Label l=Ui.Label("Na pulpicie jest "+Path.GetFileName(target)+".\n\nJeden plik .js — program i układ bloczków.\nUruchom go skrótem „Otwórz "+Project.Name+"”.",11);l.SetBounds(22,20,460,105);done.Controls.Add(l);Button run=Ui.Button("Otwórz program",Ui.Purple);run.SetBounds(23,140,161,37);run.Click+=delegate{Process.Start(link);done.Close();};done.Controls.Add(run);Button folder=Ui.Button("Pokaż plik",Ui.Raised);folder.SetBounds(195,140,132,37);folder.Click+=delegate{Process.Start("explorer.exe","/select,\""+target+"\"");};done.Controls.Add(folder);Button close=Ui.Button("Gotowe",Ui.Raised);close.SetBounds(338,140,130,37);close.Click+=delegate{done.Close();};done.Controls.Add(close);done.ShowDialog(this);}}catch(Exception e){Error(e.Message);}}
 void Features(){using(Form f=new Form{Text="Włączanie funkcji projektu",Size=new Size(480,580),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=Ui.Panel,ForeColor=Ui.Text}){Label l=Ui.Label("Wybierz aktywne grupy bloczków",16);l.SetBounds(20,18,430,35);f.Controls.Add(l);Label h=Ui.Label("Wyłączone grupy są pomijane przy uruchamianiu.\nKażdy bloczek możesz też wyłączyć przyciskiem ●.",10);h.ForeColor=Ui.Muted;h.SetBounds(22,61,425,52);f.Controls.Add(h);CheckedListBox checks=new CheckedListBox{BackColor=Ui.Bg,ForeColor=Ui.Text,BorderStyle=BorderStyle.None,CheckOnClick=true,Font=new Font("Segoe UI",12)};checks.SetBounds(23,128,420,320);foreach(string group in Catalog.Groups)checks.Items.Add(group,Project.Allows(group));f.Controls.Add(checks);Button all=Ui.Button("Włącz wszystkie",Ui.Raised);all.SetBounds(23,465,150,37);all.Click+=delegate{for(int i=0;i<checks.Items.Count;i++)checks.SetItemChecked(i,true);};f.Controls.Add(all);Button apply=Ui.Button("Zastosuj",Ui.Purple);apply.SetBounds(285,465,155,37);apply.Click+=delegate{Remember();for(int i=0;i<Catalog.Groups.Length;i++)Project.Features[Catalog.Groups[i]]=checks.GetItemChecked(i);Preview.Stop();Changed();RenderPalette();f.Close();};f.Controls.Add(apply);f.ShowDialog(this);}}
 void ImportImage(){using(OpenFileDialog d=new OpenFileDialog{Filter="Obrazy PNG / JPG / BMP / GIF|*.png;*.jpg;*.jpeg;*.bmp;*.gif",Title="Dodaj obraz do projektu .js"}){if(d.ShowDialog(this)!=DialogResult.OK)return;try{byte[] data=File.ReadAllBytes(d.FileName);if(data.Length>5*1024*1024)throw new Exception("Obraz przekracza 5 MB.");using(MemoryStream m=new MemoryStream(data))using(Image image=Image.FromStream(m)){if((long)image.Width*image.Height>16000000)throw new Exception("Obraz ma za dużą rozdzielczość (limit 16 megapikseli).");}if(Project.Assets.Sum(x=>(long)x.Value.Length)+data.Length*4L/3>28000000)throw new Exception("Limit obrazów w projekcie: około 20 MB.");Remember();string id="obraz"+(Project.Assets.Count+1);while(Project.Assets.ContainsKey(id))id+="_";Project.Assets[id]=Convert.ToBase64String(data);Block b=Block.Make("ui_image");b.A="image_"+id;b.B=id;Project.Blocks.Add(b);Changed();Render();status.Text="Zaimportowano „"+id+"”. Użyj tej nazwy w kostiumie duszka lub elemencie Obraz.";}catch(Exception e){Error(e.Message);}}}
 async void Example(int i){if(!CanClose()){examples.SelectedIndex=0;return;}Preview.Stop();Project=Examples.Create(i);filePath=null;undo.Clear();redo.Clear();dirty=false;designer.Checked=false;Render();RenderPalette();examples.SelectedIndex=0;await Preview.Start(Project);}
 void KeysDown(object sender,KeyEventArgs e){if(e.Control&&e.KeyCode==Keys.S){Save(e.Shift);e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.O){Open();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.N){New();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Enter){Export();e.SuppressKeyPress=true;}else if(e.KeyCode==Keys.F5){if(e.Shift)Preview.Stop();else{designer.Checked=false;viewTabs.SelectedIndex=0;var ignored=Preview.Start(Project);}e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Z&&!(FocusedControl(this) is TextBoxBase)){Undo();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Y&&!(FocusedControl(this) is TextBoxBase)){Redo();e.SuppressKeyPress=true;}}
 static Control FocusedControl(ContainerControl c){Control a=c.ActiveControl;while(a is ContainerControl&&((ContainerControl)a).ActiveControl!=null)a=((ContainerControl)a).ActiveControl;return a;}
 void Error(string text){status.Text=text;MessageBox.Show(this,text,"EasyJava",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 public async Task Snapshot(string path){Show();Application.DoEvents();Render();if(Project.Blocks.Count>0)await Preview.Start(Project);else Preview.Reset(Project);Application.DoEvents();using(Bitmap bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(path);}}
 public static string HelpText(){return "EASYJAVA 2\r\n\r\nBloczki klikaj albo przeciągaj z biblioteki. Istniejące bloczki przenoś za tytuł lub uchwyt.\r\n\r\nPętle, warunki i zdarzenia mają miejsce w środku. Upuść tam bloczki. Warunek z alternatywą ma drugą gałąź.\r\n\r\n● w nagłówku włącza / wyłącza bloczek. Wyłączenie pętli lub zdarzenia pomija też jego wnętrze. Funkcje w górnym pasku wyłączają całe kategorie.\r\n\r\nPODGLĄD\r\nFlaga lub F5 uruchamia projekt. ■ lub Shift+F5 zatrzymuje wszystkie skrypty. Kliknij scenę przed sterowaniem klawiszami. W podglądzie widać rzeczywiste okna i elementy GUI, duszki oraz wynik działania.\r\n\r\nPROJEKTANT GUI\r\nZaznacz Projektant GUI i przeciągaj elementy okna. Pozycje X i Y zapisują się w bloczkach. W tym trybie zdarzenia i pliki nie działają. Potem kliknij Uruchom podgląd.\r\n\r\nZAPIS I KOMPILACJA\r\nZapisz .js zachowuje jeden plik, który można uruchomić lub otworzyć w EasyJava do dalszej edycji. Kompiluj na pulpit zapisuje .js i tworzy skrót Otwórz. Node.js nie jest wymagany. Kopie zastępowanych plików trafiają do lokalnego folderu EasyJava/Kopie.\r\n\r\nGUI\r\nNajpierw dodaj elementy, nadając im unikalne identyfikatory, np. input1 i button1. Zdarzenie Kiedy kliknięto przycisk z identyfikatorem button1 reaguje na kliknięcie. Odczytaj wartość elementu zapisuje wpisany tekst do zmiennej. Wczytaj przykład Panel GUI.\r\n\r\nDUSZKI\r\nUtwórz duszka lub wybierz już istniejącego. Każdy skrypt ma własnego aktywnego duszka. Nowy projekt jest zawsze pusty. Gotowe przykłady uruchamia się wyłącznie z listy.\r\n\r\nŚrodek sceny to 0,0. Kierunek 0 oznacza prawo, 90 górę. Dostępne są ruch, lot, odbicie, dymki, kostiumy i pisak.\r\n\r\nZMIENNE I OBLICZENIA\r\nW tekście używaj {nazwa}, np. Wynik: {punkty}. Liczby możesz zapisywać z przecinkiem. Pole zaczynające się od = jest wyrażeniem, np. =punkty * 2 + 1.\r\nOperatory: + - * / % ^ == != < > <= >= && || !\r\nFunkcje: sqrt, abs, round, floor, ceil, sin, cos, tan, log, min, max, len. Funkcje używają przecinka jako separatora argumentów; liczby w wyrażeniu zapisuj z kropką.\r\nListy są numerowane od 1.\r\n\r\nOBRAZY\r\nImportuj obraz osadza go w projekcie .js. Identyfikator obrazu można wpisać w bloczku Obraz lub w polu kostiumu duszka.\r\n\r\nPLIKI\r\nKategorię Pliki włącza się w oknie Funkcje. Użyj Wybierz plik do odczytu / zapisu, a potem odczytuj lub zapisuj tekst. Zapis pyta przed zastąpieniem istniejącego pliku.\r\n\r\nPRZYKŁADY\r\nPanel GUI, licznik kliknięć, sterowanie duszkiem, rysujący robot, gra ze zbieraniem gwiazdy, lista zadań i notatnik.\r\n\r\nTo osobny edytor inspirowany Scratchem, rozwijany jako aplikacja Windows. Nie wczytuje projektów .sb3.\r\n";}
}
